using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

[McpServerToolType]
public static class WeatherTools
{
    [McpServerTool, Description("Gets current weather for a given latitude and longitude.")]
    public static async Task<string> GetCurrentWeather(
        IHttpClientFactory httpClientFactory,
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        var client = httpClientFactory.CreateClient("WeatherApi");

        var response = await client.GetFromJsonAsync<WeatherResponse>(
            $"v1/forecast?latitude={latitude}&longitude={longitude}&current=temperature_2m,wind_speed_10m");

        if (response?.Current is null)
            return "Unable to retrieve weather data.";

        return $"Temperature: {response.Current.Temperature}°C, " +
               $"Wind Speed: {response.Current.WindSpeed} km/h";
    }

    [McpServerTool, Description("Gets weather forecast for the next N days.")]
    public static async Task<string> GetForecast(
        IHttpClientFactory httpClientFactory,
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        [Description("Number of forecast days (1-7)")] int days = 3)
    {
        var client = httpClientFactory.CreateClient("WeatherApi");

        var response = await client.GetAsync(
            $"v1/forecast?latitude={latitude}&longitude={longitude}" +
            $"&daily=temperature_2m_max,temperature_2m_min&forecast_days={days}");

        response.EnsureSuccessStatusCode();
        var content = await response.Content.ReadAsStringAsync();
        return content;
    }
}

public record WeatherResponse
{
    [JsonPropertyName("current")]
    public CurrentWeather? Current { get; init; }
}

public record CurrentWeather
{
    [JsonPropertyName("temperature_2m")]
    public double Temperature { get; init; }

    [JsonPropertyName("wind_speed_10m")]
    public double WindSpeed { get; init; }
}

